import{_ as t,o,c as r,a as d}from"./app.CYXXef1p.js";const p=JSON.parse('{"title":"CLAUDE Appendix: thegent-specific and domain workflow rules","description":"","frontmatter":{},"headers":[],"relativePath":"reference/CLAUDE_THEGENT_RUNTIME_APPENDIX.md","filePath":"reference/CLAUDE_THEGENT_RUNTIME_APPENDIX.md","lastUpdated":1771835514000}'),a={name:"reference/CLAUDE_THEGENT_RUNTIME_APPENDIX.md"};function n(s,e,i,c,l,g){return o(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="claude-appendix-thegent-specific-and-domain-workflow-rules" tabindex="-1">CLAUDE Appendix: thegent-specific and domain workflow rules <a class="header-anchor" href="#claude-appendix-thegent-specific-and-domain-workflow-rules" aria-label="Permalink to &quot;CLAUDE Appendix: thegent-specific and domain workflow rules&quot;">​</a></h1><h3 id="thegent-specific-rules" tabindex="-1">thegent-Specific Rules <a class="header-anchor" href="#thegent-specific-rules" aria-label="Permalink to &quot;thegent-Specific Rules&quot;">​</a></h3><ul><li>Use tach.toml for boundary enforcement (already configured)</li><li>All new agents must use the agent runner strategy pattern</li><li><strong>Rust tooling</strong>: Prefer <code>rg</code> over <code>grep</code>, <code>fd</code> over <code>find</code>, <code>jaq</code> over <code>jq</code> for faster hook/agent execution. Hooks use grep-wrapper (routes to rg), fd-wrapper, and JQ_CMD (jaq first). For Claude Code: <code>export USE_BUILTIN_RIPGREP=0</code> to use system ripgrep (5-10x faster than bundled).</li><li>All new hooks must follow existing hook patterns in hooks/</li><li>Provider pattern: use ProviderRegistry for extensible services</li><li>MCP tools go through the standard FastMCP registration</li></ul><hr><h2 id="domain-specific-patterns" tabindex="-1">Domain-Specific Patterns <a class="header-anchor" href="#domain-specific-patterns" aria-label="Permalink to &quot;Domain-Specific Patterns&quot;">​</a></h2><h3 id="what-thegent-is" tabindex="-1">What thegent Is <a class="header-anchor" href="#what-thegent-is" aria-label="Permalink to &quot;What thegent Is&quot;">​</a></h3><p>thegent is an <strong>MCP server + agent hook system</strong> for governing AI agent lifecycle and quality. The core domain is: define agents (personas with capabilities), dispatch hooks at lifecycle events (session start, tool use, stop), enforce governance policies (cost, quality, security), and expose MCP tools for agent management. It is fundamentally an <strong>agent orchestration and governance platform</strong>.</p><h3 id="local-development-present" tabindex="-1">Local Development (Present) <a class="header-anchor" href="#local-development-present" aria-label="Permalink to &quot;Local Development (Present)&quot;">​</a></h3><p><strong>Dev stack</strong>: MCP server + CLIProxyAPIPlus proxy via process-compose. Taskfile drives setup and dev.</p><table tabindex="0"><thead><tr><th>Task</th><th>Purpose</th></tr></thead><tbody><tr><td><code>task setup</code></td><td>Install deps, build cliproxy plusplus source, ensure config, install shims</td></tr><tr><td><code>task dev</code></td><td>Build cliproxy, ensure config, start MCP + proxy (TUI)</td></tr><tr><td><code>task dev:bg</code></td><td>Same as dev, background</td></tr><tr><td><code>task dev:down</code></td><td>Stop all services</td></tr><tr><td><code>task dev:logs</code></td><td>Follow service logs</td></tr><tr><td><code>task cliproxy:build</code></td><td>Build <code>../cliproxyapi-plusplus/cli-proxy-api-plus</code></td></tr><tr><td><code>task cliproxy:ensure-config</code></td><td>Ensure cliproxy config (port, auth-dir)</td></tr><tr><td><code>task cliproxy:start</code>, <code>stop</code>, <code>restart</code></td><td>Proxy lifecycle</td></tr></tbody></table><p><strong>Proxy binary</strong>: <code>scripts/start_proxy_dev.sh</code> uses the plusplus binary when built (<code>task cliproxy:build</code>), else falls back to <code>cli-proxy-api-plus</code> from PATH. process-compose runs this wrapper for the proxy process.</p><p><strong>Ports</strong>: MCP 3847, proxy 8317. Canonical source at <code>../cliproxyapi-plusplus</code>; metrics at <code>GET /v1/metrics/providers</code>.</p><p><strong>Debug</strong>: <code>thegent run --debug</code> sets <code>THGENT_DEBUG=1</code>; proxy gets <code>-debug</code> when env set. See <code>docs/plans/DEBUG_TAGS_AND_METRICS.md</code>.</p><h3 id="key-ports-and-interfaces" tabindex="-1">Key Ports and Interfaces <a class="header-anchor" href="#key-ports-and-interfaces" aria-label="Permalink to &quot;Key Ports and Interfaces&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Port</th><th>Responsibility</th><th>Location</th></tr></thead><tbody><tr><td><strong>AgentRunner</strong></td><td>Strategy pattern for executing agent personas</td><td><code>agents/</code></td></tr><tr><td><strong>HookDispatcher</strong></td><td>Dispatches lifecycle hooks (pre/post tool use, stop, etc.)</td><td><code>hooks/hook-dispatcher/</code>, <code>hooks/*-dispatcher.sh</code></td></tr><tr><td><strong>PolicyEngine</strong></td><td>Evaluates governance rules (cost caps, quality gates, security)</td><td><code>hooks/qa-policy-engine.sh</code>, <code>contracts/</code></td></tr><tr><td><strong>MCPToolRegistry</strong></td><td>Registers and serves MCP tools to connected clients</td><td>MCP server entry point</td></tr><tr><td><strong>CommandRegistry</strong></td><td>CLI commands for agent management, DAG compilation, spec ops</td><td><code>commands/</code></td></tr><tr><td><strong>ContractStore</strong></td><td>Stores and validates governance contracts and policies</td><td><code>contracts/</code></td></tr></tbody></table><h3 id="provider-registry-and-agent-strategy" tabindex="-1">Provider Registry and Agent Strategy <a class="header-anchor" href="#provider-registry-and-agent-strategy" aria-label="Permalink to &quot;Provider Registry and Agent Strategy&quot;">​</a></h3><ul><li><strong>Agent personas</strong> live in <code>agents/</code> as markdown definitions. New agents = new <code>.md</code> file describing the persona, capabilities, and constraints.</li><li><strong>Hooks</strong> follow a strict naming and dispatch pattern. The dispatcher routes events to matching hook scripts. New hooks = new <code>.sh</code> file in <code>hooks/</code> following the naming convention (<code>qa-*.sh</code> for quality gates, <code>pre-*.sh</code> for pre-tool hooks, etc.).</li><li><strong>Commands</strong> in <code>commands/</code> define CLI-accessible operations (DAG compilation, ledger init, spec hashing). New commands = new entry in <code>commands/</code> + registration.</li><li><strong>Contracts</strong> define governance policies (cost limits, SLOs, migration rules). New governance rule = new contract JSON in <code>contracts/</code>.</li></ul><h3 id="common-anti-patterns-to-avoid" tabindex="-1">Common Anti-Patterns to Avoid <a class="header-anchor" href="#common-anti-patterns-to-avoid" aria-label="Permalink to &quot;Common Anti-Patterns to Avoid&quot;">​</a></h3><ul><li><strong>Direct MCP message handling in domain logic</strong> -- MCP protocol concerns stay in the MCP server layer. Domain logic (agents, hooks, policies) must not import or depend on MCP transport</li><li><strong>Custom agent discovery</strong> -- Use the agent registry pattern. Never glob for agent files at runtime outside the registry</li><li><strong>Hooks that bypass the dispatcher</strong> -- All hooks fire through <code>hook-dispatcher/</code>. Never call hook scripts directly from application code</li><li><strong>Inline governance rules</strong> -- Cost caps, quality thresholds, and policy rules belong in <code>contracts/</code> or <code>hooks/hook-config.yaml</code>, not hardcoded in hook scripts</li><li><strong>Monolithic hook scripts</strong> -- Shared logic goes in <code>hooks/lib/</code>. Hook scripts should be thin dispatchers that call library functions</li></ul><h3 id="sitback-agent" tabindex="-1">Sitback Agent <a class="header-anchor" href="#sitback-agent" aria-label="Permalink to &quot;Sitback Agent&quot;">​</a></h3><p><code>thegent sitback</code> launches Claude Code with a Sitback Agent persona: dashboard (cockpit + terminals + ps), FastMCP tools first, CLI fallback. Skills: <code>skills/sitback-agent/</code> (default), overridable via <code>--skill</code>. MCP precondition: <code>thegent serve</code> for full toolset.</p><h3 id="workflow-triggers-skill-mcp-instruction" tabindex="-1">Workflow Triggers (Skill / MCP / Instruction) <a class="header-anchor" href="#workflow-triggers-skill-mcp-instruction" aria-label="Permalink to &quot;Workflow Triggers (Skill / MCP / Instruction)&quot;">​</a></h3><p>Idea/task prompts, quality green, and &quot;next thing to do&quot; are wired at multiple levels:</p><table tabindex="0"><thead><tr><th>Level</th><th>Location</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Hook</strong></td><td><code>hooks/prompt-submit-guard.sh</code></td><td>UserPromptSubmit: pattern-detect, inject instructions to agent context</td></tr><tr><td><strong>Skill</strong></td><td><code>skills/agent-orchestra/SKILL.md</code>, <code>skills/sitback-agent/SKILL.md</code></td><td>Baked-in workflow section; agents with these skills follow it</td></tr><tr><td><strong>MCP resource</strong></td><td><code>thegent://workflow/triggers</code></td><td>URI-addressable; agent can read when needed</td></tr><tr><td><strong>MCP resource</strong></td><td><code>thegent://workstream</code></td><td>Work stream (canonical backlog)</td></tr><tr><td><strong>MCP prompts</strong></td><td><code>thegent_workflow_idea</code>, <code>thegent_workflow_quality_green</code>, <code>thegent_workflow_next_item</code>, <code>thegent_workflow_gardening</code></td><td>Template prompts for structured invocation</td></tr><tr><td><strong>MCP resource</strong></td><td><code>thegent://workflow/gardening</code></td><td>Gardening workflow (converge to empty backlog + green)</td></tr><tr><td><strong>MCP tool</strong></td><td><code>thegent_do_next</code></td><td>Find next actionable items from WORK_STREAM (canonical), PLAN_STATUS, FR_TRACKER, docs/plans/, escalation; returns prompt_suggestion for <code>thegent run</code></td></tr><tr><td><strong>CLI</strong></td><td><code>thegent plan next</code></td><td>Same as thegent_do_next</td></tr></tbody></table><p><strong>Unified work stream</strong>: Single source of truth is <code>docs/reference/WORK_STREAM.md</code>. All agents read it for work items; claim in CLAIMED before starting; update COMPLETED when done. Incorporator agent (<code>work-stream-incorporator</code>) merges fragments from plans, research, specs into the stream. See <a href="./docs/reference/UNIFIED_WORK_STREAM_DESIGN.html">UNIFIED_WORK_STREAM_DESIGN.md</a>.</p><p><strong>Idea/task</strong> → dump research to docs/research/, specs to docs/docset/, work items to unified stream. <strong>Quality green</strong> → <code>task quality-a-r</code>. <strong>Next item</strong> → <code>thegent_do_next</code> (or read WORK_STREAM.md), pick highest-priority, execute via <code>thegent run</code>/<code>--bg</code> with <code>prompt_suggestion</code>. <strong>Gardening</strong> → check gov traceability, tests, plan items; dispatch; converge to empty backlog and complete green (<code>thegent govern go health</code>, <code>go cycle</code>, <code>task quality-a-r</code>).</p><h3 id="cycleloop-loops" tabindex="-1">Cycleloop Loops <a class="header-anchor" href="#cycleloop-loops" aria-label="Permalink to &quot;Cycleloop Loops&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command / Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><code>thegent orchestrate loop &quot;prompt&quot; &quot;todo&quot;</code></td><td>Run Cycleloop loop (worker + checker)</td></tr><tr><td><code>thegent orchestrate loop-send &lt;session_id&gt; &lt;prompt&gt;</code></td><td>Send next prompt to running loop (human/agent takeover)</td></tr><tr><td><code>thegent orchestrate loop-stop &lt;session_id&gt;</code></td><td>Stop loop</td></tr><tr><td><code>thegent takeover &lt;session&gt;</code></td><td>Attach to tmux session; human types next prompt</td></tr><tr><td><code>thegent_loop_takeover</code> (MCP)</td><td>Agent injects prompt into running loop</td></tr><tr><td><code>--continuation &lt;session_id&gt;</code></td><td>Resume from prior session (adds resumption appendix)</td></tr><tr><td><code>--resume</code> (Codex/Claude)</td><td>Use when agent supports native resume</td></tr></tbody></table><p><strong>Premature session end:</strong> If Codex/Claude supports <code>--resume</code>, use it. Otherwise: <code>thegent run agent --continuation &lt;prior_session_id&gt; &quot;Task&quot;</code> — builds context from prior stdout + resumption appendix.</p><h3 id="wbs-agent-coordination-multi-agent-do-all" tabindex="-1">WBS Agent Coordination (Multi-Agent &quot;Do All&quot;) <a class="header-anchor" href="#wbs-agent-coordination-multi-agent-do-all" aria-label="Permalink to &quot;WBS Agent Coordination (Multi-Agent &quot;Do All&quot;)&quot;">​</a></h3><p>When the user says <strong>&quot;do all&quot;</strong> or assigns work to multiple agents:</p><ol><li><strong>Read</strong> <code>docs/reference/WORK_STREAM.md</code> (canonical) — or <code>docs/plans/02-UNIFIED-WBS.md</code> + <code>docs/reference/WBS_AGENT_PROGRESS.md</code> for WBS-only coordination</li><li><strong>Claim before starting</strong>: Append your work items to the <strong>CLAIMED</strong> table in <code>WORK_STREAM.md</code> (or <code>WBS_AGENT_PROGRESS.md</code> if using WBS-only) with a unique agent_id (e.g. <code>agent-1</code>, <code>runner-A</code>)</li><li><strong>Avoid overlap</strong>: Do NOT pick items already in CLAIMED. Pick an equal batch of unclaimed items.</li><li><strong>Update progress</strong>: When done, move items from CLAIMED to COMPLETED and update source file (e.g. <code>02-UNIFIED-WBS.md</code>) status to DONE</li></ol><p><strong>Preferred</strong>: Use <code>WORK_STREAM.md</code> — single file for all work types. <code>WBS_AGENT_PROGRESS.md</code> remains for backward compatibility with WBS-only &quot;do all&quot; flows.</p><h3 id="where-to-add-new-functionality" tabindex="-1">Where to Add New Functionality <a class="header-anchor" href="#where-to-add-new-functionality" aria-label="Permalink to &quot;Where to Add New Functionality&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Want to add...</th><th>Put it in...</th></tr></thead><tbody><tr><td>New agent persona</td><td><code>agents/&lt;persona-name&gt;.md</code> -- follows existing agent template</td></tr><tr><td>New lifecycle hook</td><td><code>hooks/&lt;event&gt;-&lt;name&gt;.sh</code> + register in <code>hooks/hook-config.yaml</code></td></tr><tr><td>New governance policy</td><td><code>contracts/&lt;policy&gt;.json</code> + wire into <code>qa-policy-engine.sh</code></td></tr><tr><td>New MCP tool</td><td>MCP server registration (FastMCP pattern)</td></tr><tr><td>New CLI command</td><td><code>commands/&lt;command&gt;/</code> + register in command dispatch</td></tr><tr><td>New quality gate</td><td><code>hooks/qa-&lt;gate-name&gt;.sh</code> following existing <code>qa-*.sh</code> patterns</td></tr><tr><td>Shared hook utility</td><td><code>hooks/lib/&lt;utility&gt;.sh</code> -- sourced by hook scripts, never called directly</td></tr></tbody></table><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../reference/WORK_STREAM.html">WORK_STREAM.md</a> — canonical backlog</li><li><a href="./../plans/00-MASTER-INDEX.html">00-MASTER-INDEX.md</a> — plan index</li></ul><hr><h2 id="extension-summary" tabindex="-1">EXTENSION_SUMMARY <a class="header-anchor" href="#extension-summary" aria-label="Permalink to &quot;EXTENSION_SUMMARY&quot;">​</a></h2><p><strong>Extended on:</strong> 2026-02-17 <strong>Extended by:</strong> Claude Code</p><h3 id="changes-made" tabindex="-1">Changes Made <a class="header-anchor" href="#changes-made" aria-label="Permalink to &quot;Changes Made&quot;">​</a></h3><ol><li>Added practical implementation patterns</li><li>Added configuration examples</li><li>Enhanced cross-references to related documentation</li></ol><h3 id="cross-references-added" tabindex="-1">Cross-References Added <a class="header-anchor" href="#cross-references-added" aria-label="Permalink to &quot;Cross-References Added&quot;">​</a></h3><ul><li>Related research and implementation guides</li><li>WORK_STREAM.md for tracking</li></ul><h3 id="practical-additions" tabindex="-1">Practical Additions <a class="header-anchor" href="#practical-additions" aria-label="Permalink to &quot;Practical Additions&quot;">​</a></h3><ul><li>Implementation templates</li><li>Configuration examples</li><li>Best practices</li></ul>',47)])])}const u=t(a,[["render",n]]);export{p as __pageData,u as default};
